//! WinUI 3 projection generated by `winui-bindgen`, plus app startup and a few helpers.
//!
//! The projection only carries the members this app calls; add more to
//! `crates/winui-bindgen/filter.txt` and rerun `cargo run -p winui-bindgen`.

mod bootstrap;
mod ext;
mod start;

/// Output of `winui-bindgen` (`src/generated/`). Do not edit by hand.
#[allow(non_snake_case, non_camel_case_types, non_upper_case_globals, dead_code, clippy::all)]
mod generated {
    pub mod app_bindings;
    pub mod bindings;
}

pub use windows_core::{Error, HSTRING, IInspectable, Interface, Ref, Result};

pub use crate::{ext::*, generated::bindings::*, start::run};
